mapper.update:
UPDATE tb_att_plan_n
   SET shift_type_code             = #{planShiftCode}
      ,time_and_attendance_code    = #{planAttendanceDetail}
      ,time_attend_detail_code     = #{planAttendDetailReason}
      ,night_shift_flag            = #{planDayNight}
      ,overtime_sum_hours          = #{planOT}
      ,last_update_user_id         = #{applicationUserId}
      ,last_update_date            = SYSDATE
      ,base_time_attend_apply_flag = 'N'
 WHERE employee_no = #{employeeNo}
   AND time_and_attendance_date = trunc(to_date(#{planDate}, 'dd/mm/yyyy'))
   AND subsidiary_code = #{subsidiaryCode}

UPDATE tb_att_result_n
   SET shift_type_code                = #{actualShiftCode}
      ,time_and_attendance_code       = #{actualAttendanceDetail}
      ,time_attend_detail_code        = #{actualAttendDetailReason}
      ,night_shift_flag               = #{actualDayNight}
      ,work_hours                     = (SELECT CASE WHEN attendance_days = 1 
                                                     THEN CASE WHEN #{actualShiftCode} LIKE '3%' THEN 9.5 
                                                     ELSE lgvpay_info_pkg.get_type_work_hours(#{subsidiaryCode},trunc(to_date(#{actualDate}, 'dd/mm/yyyy')),'21','1A',8,'perfect_work_hours') END /*HMT_20210323*/
                                                     WHEN attendance_days = 0.5
                                                     THEN CASE WHEN #{actualShiftCode} LIKE '3%' THEN 4 
                                                     ELSE lgvpay_info_pkg.get_type_work_hours(#{subsidiaryCode},trunc(to_date(#{actualDate}, 'dd/mm/yyyy')),'21','1A',8,'perfect_work_hours')/2 END /*HMT_20210323*/
                                                     ELSE 0
                                                     END 
                                         FROM   tb_att_code_c
                                         WHERE  subsidiary_code          = #{subsidiaryCode}
                                         AND    time_and_attendance_code = #{actualAttendanceDetail})
      ,work_start_time                = #{actualStartTm}
      ,evening_meal_flag              = #{actualDinnerChk}
      ,overtime_sum_hours             = #{actualOT}
      ,weekday_overtime_hours         = #{weekday}
      ,holiday_overtime_hours         = #{weekdayHoliday}
      ,public_holiday_overtime_hours  = #{publicHoliday}
      ,weekday_night_overtime_hours   = #{atNightWeekday}
      ,weekday_ot_af_night_work_hours = #{atNightWeekdayAfterOT}
      ,holiday_night_overtime_hours   = #{atNightWeekdayHoliday}
      ,public_holiday_night_ot_hours  = #{atNightPublicHoliday}
      ,normal_night_overtime_hours    = #{nightNormal}
      ,tardy_hours                    = #{deductionLateness}
      ,early_leave_hours              = #{deductionLeavingEarly}
      ,going_out_hours                = #{deductionGoingOut}
      ,special_bonus_hours            = #{specialBonus}
      ,helpcall_support_hours         = #{helpCall}
      ,time_attend_input_reason_desc  = #{timeAttendInputReasonDesc}
      ,last_update_user_id            = #{applicationUserId}
      ,last_update_date               = SYSDATE
      ,base_time_attend_apply_flag    = 'N'
 WHERE employee_no = #{employeeNo}
   AND time_and_attendance_date = trunc(to_date(#{actualDate}, 'dd/mm/yyyy'))
   AND subsidiary_code = #{subsidiaryCode}
